<?php namespace App\Filament\Resources; use App\Filament\Resources\UserResource\Pages; use App\Models\User; use Filament\Actions\{Action,EditAction}; use Filament\Forms\Components\{Select,Toggle}; use Filament\Schemas\Schema; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Filters\SelectFilter; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder; use Illuminate\Support\Facades\Password; class UserResource extends AdminResource {protected static ?string $model=User::class;protected static ?string $recordTitleAttribute='name';protected static string|null|\BackedEnum $navigationIcon='heroicon-o-users';protected static string|\UnitEnum|null $navigationGroup='Communauté';protected static ?int $navigationSort=4;protected static ?string $navigationLabel='Utilisateurs';public static function canCreate():bool{return false;}public static function getEloquentQuery():Builder{return parent::getEloquentQuery()->withCount('ownedRestaurants');}public static function form(Schema $s):Schema{return $s->components([Select::make('role')->options(['user'=>'Utilisateur','restaurant_owner'=>'Restaurateur','admin'=>'Administrateur'])->required(),Select::make('status')->options(['active'=>'Actif','disabled'=>'Désactivé'])->required(),Toggle::make('must_change_password')->label('Forcer le changement de mot de passe')]);}public static function table(Table $t):Table{return $t->columns([TextColumn::make('name')->searchable()->description(fn(User $u)=>$u->email),TextColumn::make('role')->badge(),TextColumn::make('status')->badge(),TextColumn::make('email_verified_at')->label('Email vérifié')->dateTime('d/m/Y')->placeholder('Non'),TextColumn::make('owned_restaurants_count')->label('Restaurants')->numeric(),TextColumn::make('must_change_password')->label('MDP à changer')->badge()->formatStateUsing(fn($state)=>$s?'Oui':'Non'),TextColumn::make('created_at')->label('Créé')->since()->sortable()])->filters([SelectFilter::make('role')->options(['user'=>'Utilisateur','restaurant_owner'=>'Restaurateur','admin'=>'Administrateur']),SelectFilter::make('status')->options(['active'=>'Actif','disabled'=>'Désactivé'])])->recordActions([EditAction::make(),Action::make('reset')->label('Réinitialiser MDP')->requiresConfirmation()->action(function(User $u):void{Password::sendResetLink(['email'=>$u->email]);app(\App\Services\AdminAudit::class)->record('user.password_reset_sent',$u);})])->defaultSort('created_at','desc');}public static function getPages():array{return ['index'=>Pages\ListUsers::route('/'),'edit'=>Pages\EditUser::route('/{record}/edit')];}}
